insert into public.products (id, slug, name, category_id, short_description, full_description, images, tags, featured, enabled_for_sale, sort_order) values ('ginger-shot', 'ginger-shot', 'Ginger Shot', 'wellness-shots', 'A warming, zesty ginger blend for your daily wellness routine.', array['Our Ginger Shot is bold by design: a warming, zesty hit of ginger made to be the easiest part of your morning.', 'Keep one in the fridge, take it with breakfast or before you head out, and let the flavour wake you up.']::text[], '[{"src":"/images/products/ginger-shot-placeholder.webp","alt":"Ginger Shot: temporary bottle artwork with a placeholder Naturo label","placeholder":true,"width":900,"height":1350}]'::jsonb, array['daily-routine', 'citrus', 'warming', 'bestseller-candidate']::text[], true, true, 0) on conflict (id) do nothing;
