insert into public.products (id, slug, name, category_id, short_description, full_description, images, tags, featured, enabled_for_sale, sort_order) values ('glow-shot', 'glow-shot', 'Glow Shot', 'wellness-shots', 'A fresh botanical blend for people who enjoy making natural wellness part of their everyday routine.', array['Glow Shot is our fresh, green-and-golden botanical blend: bright, clean and easy to love.', 'Made for people who enjoy small, natural rituals, whether that''s with breakfast, after the gym or mid-afternoon.']::text[], '[{"src":"/images/products/glow-shot-placeholder.webp","alt":"Glow Shot: temporary bottle artwork with a placeholder Naturo label","placeholder":true,"width":900,"height":1350}]'::jsonb, array['daily-routine', 'botanical', 'fresh']::text[], true, true, 1) on conflict (id) do nothing;
