insert into public.products (id, slug, name, category_id, short_description, full_description, images, tags, featured, enabled_for_sale, sort_order) values ('pineapple-shot', 'pineapple-shot', 'Pineapple Shot', 'wellness-shots', 'A sweet, tropical blend with naturally occurring vitamin C.', array['Sunshine in a small bottle. Our Pineapple Shot is sweet, tropical and bright, with the naturally occurring vitamin C found in pineapple.', 'A favourite for anyone who wants their wellness ritual to taste like a holiday.']::text[], '[{"src":"/images/products/pineapple-shot-placeholder.webp","alt":"Pineapple Shot: temporary bottle artwork with a placeholder Naturo label","placeholder":true,"width":900,"height":1350}]'::jsonb, array['tropical', 'sweet', 'citrus']::text[], true, true, 3) on conflict (id) do nothing;
