insert into public.products (id, slug, name, category_id, short_description, full_description, images, tags, featured, enabled_for_sale, sort_order) values ('mens-vitality-shot', 'mens-vitality-shot', 'Men’s Vitality Shot', 'wellness-shots', 'A natural blend inspired by traditional ingredients and associated with energy and stamina.', array['Grounded, earthy and confident, our Men’s Vitality Shot draws inspiration from traditional ingredients long associated with energy and stamina.', 'A deliberate, no-fuss ritual for busy days.']::text[], '[{"src":"/images/products/mens-vitality-placeholder.webp","alt":"Men’s Vitality Shot: temporary bottle artwork with a placeholder Naturo label","placeholder":true,"width":900,"height":1350}]'::jsonb, array['daily-routine', 'earthy', 'traditional-inspired']::text[], false, true, 4) on conflict (id) do nothing;
