insert into public.products (id, slug, name, category_id, short_description, full_description, images, tags, featured, enabled_for_sale, sort_order) values ('maheu', 'maheu', 'Maheu', 'traditional-favourites', 'A much-loved Zimbabwean favourite, freshly prepared and bottled to bring a familiar taste into everyday life.', array['Maheu is a taste of home for so many Zimbabweans. We prepare ours fresh and bottle it so that a familiar favourite fits into modern life.', 'Enjoy it chilled, on the go, or shared with the family.']::text[], '[{"src":"/images/products/maheu-placeholder.webp","alt":"Maheu: temporary bottle artwork with a placeholder Naturo label","placeholder":true,"width":900,"height":1350}]'::jsonb, array['traditional', 'heritage', 'family']::text[], true, true, 5) on conflict (id) do nothing;
