insert into public.products (id, slug, name, category_id, short_description, full_description, images, tags, featured, enabled_for_sale, sort_order) values ('muvhee', 'muvhee', 'Muvhee', 'traditional-favourites', 'A traditional drink presented in a modern, convenient bottled format.', array['Muvhee brings a traditional drink into a modern, convenient bottle, with all the character you remember and none of the fuss.', 'Proudly part of our heritage range.']::text[], '[{"src":"/images/products/muvhee-placeholder.webp","alt":"Muvhee: temporary bottle artwork with a placeholder Naturo label","placeholder":true,"width":900,"height":1350}]'::jsonb, array['traditional', 'heritage']::text[], false, true, 6) on conflict (id) do nothing;
