insert into public.products (id, slug, name, category_id, short_description, full_description, images, tags, featured, enabled_for_sale, sort_order) values ('ginger-lemon-carrot-tea', 'ginger-lemon-carrot-tea', 'Ginger, Lemon & Carrot Tea', 'teas-and-powders', 'A comforting blend inspired by familiar ingredients, ideal for a soothing cup at home, at work, or on the move.', array['A comforting cup built around familiar ingredients: warming ginger, bright lemon and earthy carrot.', 'Brew it when you want a calm moment, at home, at your desk or wherever the day takes you.']::text[], '[{"src":"/images/products/herbal-tea-placeholder.webp","alt":"Ginger, Lemon & Carrot Tea: temporary pouch artwork with a placeholder Naturo label","placeholder":true,"width":900,"height":1350}]'::jsonb, array['tea-moment', 'citrus', 'warming']::text[], true, true, 7) on conflict (id) do nothing;
